window.HYDRO_DEMO_QUESTIONS.push(...[{"id":"V2-C1-F401-V1","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Soit une fonction définie par \\(f(x)=\\sqrt{3x-12}\\). Quelle condition sur x permet de calculer f dans l'ensemble des réels ?","a":["\\(x>4\\)","\\(x\\ge4\\)","\\(x\\le4\\)","\\(x\\ne4\\)"],"correct":1,"why":"Le radicande doit être positif ou nul : 3x-12≥0.","active":true,"family":"V2-C1-F401"},{"id":"V2-C1-F401-V2","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant affirme que \\(g(x)=\\sqrt{7-2x}\\) n'est définie que si \\(x<7/2\\). Quelle correction faut-il apporter ?","a":["Inclure \\(x=7/2\\), car la racine carrée de zéro existe.","Exclure aussi \\(x=0\\), car la racine s'annule en zéro.","Inverser le sens de l'inégalité, sans inclure la borne.","Accepter l'affirmation : le radicande doit être strictement positif."],"correct":0,"why":"L'inégalité 7-2x≥0 admet la borne.","active":true,"family":"V2-C1-F401"},{"id":"V2-C1-F401-V3","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"On modélise un indice environnemental par \\(I(t)=\\sqrt{t-5}\\), où t désigne le temps en jours. À partir de quel instant ce modèle fournit-il une valeur réelle ?","a":["Strictement après le jour 5.","Du jour 0 au jour 5 inclus.","À tout instant positif.","À partir du jour 5 inclus."],"correct":3,"why":"La racine est réelle lorsque t-5≥0.","active":true,"family":"V2-C1-F401"},{"id":"V2-C1-F402-V1","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=\\frac{x+4}{2x-6}\\). Quelle valeur doit-on exclure du domaine, et pour quelle raison ?","a":["\\(x=-4\\), car le numérateur s'annule.","\\(x=6\\), car le dénominateur s'annule.","\\(x=3\\), car le dénominateur s'annule.","\\(x=0\\), car tout quotient est interdit en zéro."],"correct":2,"why":"2x-6=0 équivaut à x=3.","active":true,"family":"V2-C1-F402"},{"id":"V2-C1-F402-V2","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Dans l'étude de \\(g(x)=\\frac{x-2}{x^2-4}\\), quelle est l'erreur d'un étudiant qui simplifie et retient directement le domaine de \\(1/(x+2)\\) ?","a":["Il exclut à tort x=-2 du domaine initial.","Il obtient une expression non égale à g pour tout x autorisé.","Il oublie que x=2 reste exclu du domaine initial.","Il devrait également exclure x=0."],"correct":2,"why":"Une simplification algébrique n'ajoute pas de valeur au domaine initial.","active":true,"family":"V2-C1-F402"},{"id":"V2-C1-F402-V3","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Pour un indicateur \\(R(x)=\\frac{1}{x-8}\\), le calcul est impossible en x=8. Quelle propriété explique cette impossibilité ?","a":["L'inverse d'un nombre positif n'existe pas.","La division par zéro n'est pas définie dans R.","Le numérateur doit être strictement inférieur au dénominateur.","Une fonction rationnelle ne peut être définie en un entier."],"correct":1,"why":"Le dénominateur est nul au point 8.","active":true,"family":"V2-C1-F402"},{"id":"V2-C1-F403-V1","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Quelle identité caractérise une fonction paire définie sur un domaine symétrique par rapport à zéro ?","a":["\\(f(-x)=-f(x)\\).","\\(f(x)=0\\) pour tout x.","\\(f(-x)=f(x)\\) (pour tout x du domaine).","\\(f(-x)=1/f(x)\\)."],"correct":2,"why":"La symétrie par rapport à l'axe des ordonnées conserve les valeurs.","active":true,"family":"V2-C1-F403"},{"id":"V2-C1-F403-V2","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Une courbe est symétrique par rapport à l'axe vertical. Quelle relation doivent satisfaire les ordonnées aux abscisses opposées ?","a":["\\(f(-x)=-f(x)\\).","\\(f(-x)=f(x)\\) (pour tout x du domaine).","\\(f(x)=0\\) pour tout x.","\\(f(-x)=1/f(x)\\)."],"correct":1,"why":"La symétrie par rapport à l'axe des ordonnées conserve les valeurs.","active":true,"family":"V2-C1-F403"},{"id":"V2-C1-F403-V3","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant veut vérifier la parité de \\(f(x)=x^2+4\\). Quelle relation doit-il établir ?","a":["\\(f(-x)=f(x)\\) (pour tout x du domaine).","\\(f(-x)=-f(x)\\).","\\(f(x)=0\\) pour tout x.","\\(f(-x)=1/f(x)\\)."],"correct":0,"why":"La symétrie par rapport à l'axe des ordonnées conserve les valeurs.","active":true,"family":"V2-C1-F403"},{"id":"V2-C1-F404-V1","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Quelle condition doit vérifier x pour que \\(\\ln(x-2)\\) soit un réel ?","a":["Supérieur ou égal à 2.","Strictement inférieur à 2.","Strictement supérieur à 2.","Différent de 2, sans autre restriction."],"correct":2,"why":"L'argument du logarithme doit être strictement positif.","active":true,"family":"V2-C1-F404"},{"id":"V2-C1-F404-V2","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant inclut x=3 dans le domaine de \\(g(x)=\\ln(x-3)\\). Quelle condition correcte faut-il retenir ?","a":["Supérieur ou égal à 3.","Strictement supérieur à 3.","Strictement inférieur à 3.","Différent de 3, sans autre restriction."],"correct":1,"why":"L'argument du logarithme doit être strictement positif.","active":true,"family":"V2-C1-F404"},{"id":"V2-C1-F404-V3","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Un indice logarithmique \\(I(t)=\\ln(t-4)\\) ne peut être calculé que pour des instants admissibles. Quelle condition s'impose ?","a":["Supérieur ou égal à 4.","Strictement supérieur à 4.","Strictement inférieur à 4.","Différent de 4, sans autre restriction."],"correct":1,"why":"L'argument du logarithme doit être strictement positif.","active":true,"family":"V2-C1-F404"},{"id":"V2-C1-F405-V1","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Une fonction périodique est donnée par \\(f(t)=\\sin(2t)\\). Quelle est sa période fondamentale ?","a":["\\(2\\pi\\)","\\(2\\pi/2\\)","\\(3\\pi\\)","\\(\\pi/2\\)"],"correct":1,"why":"L'argument 2t doit augmenter de 2π.","active":true,"family":"V2-C1-F405"},{"id":"V2-C1-F405-V2","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Une mesure météorologique reproduit son motif lorsque son argument augmente de 2π. Pour \\(g(t)=\\cos(3t)\\), quelle durée correspond à un motif complet ?","a":["\\(2\\pi/3\\)","\\(2\\pi\\)","\\(4\\pi\\)","\\(\\pi/3\\)"],"correct":0,"why":"L'argument 3t doit augmenter de 2π.","active":true,"family":"V2-C1-F405"},{"id":"V2-C1-F405-V3","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant attribue à \\(\\sin(4t)\\) la période 2π du sinus usuel. Quelle période minimale positive doit-il retenir ?","a":["\\(2\\pi\\)","\\(5\\pi\\)","\\(\\pi/4\\)","\\(2\\pi/4\\)"],"correct":3,"why":"L'argument 4t doit augmenter de 2π.","active":true,"family":"V2-C1-F405"},{"id":"V2-C1-F406-V1","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Quelle égalité caractérise la continuité de f au point a de son domaine ?","a":["\\(\\lim_{x\\to a} f(x)=f(a)\\)","\\(f(a)=0\\)","\\(f'(a)=0\\)","La limite vaut nécessairement 1."],"correct":0,"why":"La limite bilatérale doit exister et être égale à la valeur de la fonction.","active":true,"family":"V2-C1-F406"},{"id":"V2-C1-F406-V2","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Une courbe est étudiée en un point où sa valeur est connue. Quelle relation entre la valeur et la limite garantit l'absence de discontinuité ?","a":["\\(f(a)=0\\)","\\(f'(a)=0\\)","La limite vaut nécessairement 1.","\\(\\lim_{x\\to a} f(x)=f(a)\\)"],"correct":3,"why":"La limite bilatérale doit exister et être égale à la valeur de la fonction.","active":true,"family":"V2-C1-F406"},{"id":"V2-C1-F406-V3","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant calcule la limite de f en a mais ne la compare pas à f(a). Quelle condition complète de continuité doit-il vérifier ?","a":["\\(f(a)=0\\)","\\(f'(a)=0\\)","\\(\\lim_{x\\to a} f(x)=f(a)\\)","La limite vaut nécessairement 1."],"correct":2,"why":"La limite bilatérale doit exister et être égale à la valeur de la fonction.","active":true,"family":"V2-C1-F406"},{"id":"V2-C1-F407-V1","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Si les limites latérales d'une fonction en a sont finies mais distinctes, quelle conclusion sur sa limite bilatérale est correcte ?","a":["La limite bilatérale est la moyenne des deux limites.","La limite bilatérale n'existe pas.","La limite bilatérale est leur somme.","La limite bilatérale vaut zéro."],"correct":1,"why":"La limite bilatérale exige l'égalité des limites à gauche et à droite.","active":true,"family":"V2-C1-F407"},{"id":"V2-C1-F407-V2","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Un capteur théorique présente des niveaux différents avant et après un seuil. Quelle limite bilatérale possède son modèle au seuil ?","a":["La limite bilatérale est la moyenne des deux limites.","La limite bilatérale n'existe pas.","La limite bilatérale est leur somme.","La limite bilatérale vaut zéro."],"correct":1,"why":"La limite bilatérale exige l'égalité des limites à gauche et à droite.","active":true,"family":"V2-C1-F407"},{"id":"V2-C1-F407-V3","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant prend la moyenne des deux limites latérales distinctes comme limite bilatérale. Quelle correction faut-il retenir ?","a":["La limite bilatérale n'existe pas.","La limite bilatérale est la moyenne des deux limites.","La limite bilatérale est leur somme.","La limite bilatérale vaut zéro."],"correct":0,"why":"La limite bilatérale exige l'égalité des limites à gauche et à droite.","active":true,"family":"V2-C1-F407"},{"id":"V2-C1-F408-V1","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Quelle hypothèse centrale permet d'appliquer le théorème des valeurs intermédiaires sur un segment [a,b] ?","a":["La stricte croissance uniquement.","La dérivabilité seconde uniquement.","La continuité de la fonction sur le segment.","L'égalité des valeurs aux bornes uniquement."],"correct":2,"why":"La continuité sur un intervalle garantit toutes les valeurs intermédiaires.","active":true,"family":"V2-C1-F408"},{"id":"V2-C1-F408-V2","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Une grandeur évolue d'un niveau initial à un niveau final. Quelle propriété assure qu'elle atteint chaque valeur située entre ces niveaux ?","a":["La stricte croissance uniquement.","La continuité de la fonction sur le segment.","La dérivabilité seconde uniquement.","L'égalité des valeurs aux bornes uniquement."],"correct":1,"why":"La continuité sur un intervalle garantit toutes les valeurs intermédiaires.","active":true,"family":"V2-C1-F408"},{"id":"V2-C1-F408-V3","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant invoque le TVI pour une fonction présentant un saut. Quelle propriété doit-il vérifier sur tout le segment ?","a":["La continuité de la fonction sur le segment.","La stricte croissance uniquement.","La dérivabilité seconde uniquement.","L'égalité des valeurs aux bornes uniquement."],"correct":0,"why":"La continuité sur un intervalle garantit toutes les valeurs intermédiaires.","active":true,"family":"V2-C1-F408"},{"id":"V2-C1-F409-V1","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Soit une fonction f définie sur un intervalle ouvert contenant a. Quelle expression définit son nombre dérivé en a, lorsque cette limite existe ?","a":["\\(\\lim_{h\\to0}\\frac{f(a+h)+f(a)}h\\)","\\(\\lim_{h\\to0}[f(a+h)-f(a)]\\)","\\(\\lim_{h\\to0}\\frac{f(a+h)-f(a)}h\\)","\\(\\lim_{h\\to0}\\frac{f(a)-f(h)}h\\)"],"correct":2,"why":"Le taux d'accroissement est la variation de f divisée par la variation de la variable.","active":true,"family":"V2-C1-F409"},{"id":"V2-C1-F409-V2","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Pour étudier la dérivabilité de f au point a=2, un étudiant calcule \\(\\lim_{x\\to2}\\frac{f(x)-f(2)}{x}\\). Quelle correction doit-il apporter au dénominateur ?","a":["Remplacer x par \\(x+2\\).","Remplacer x par \\(x-2\\).","Remplacer x par \\(f(x)-2\\).","Conserver x, car il tend vers 2."],"correct":1,"why":"Le dénominateur est la différence entre les deux abscisses.","active":true,"family":"V2-C1-F409"},{"id":"V2-C1-F409-V3","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Une grandeur G varie avec le temps. Quel quotient faut-il faire tendre vers une limite lorsque h tend vers zéro pour obtenir sa vitesse instantanée au temps t ?","a":["\\([G(t+h)-G(t)]/h\\)","\\([G(t+h)-G(t)]/t\\)","\\(G(t+h)/h\\)","\\([G(t+h)+G(t)]/h\\)"],"correct":0,"why":"La vitesse instantanée est la limite du taux de variation moyen.","active":true,"family":"V2-C1-F409"},{"id":"V2-C1-F410-V1","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"La courbe représentative d'une fonction f admet en A=(a,f(a)) une tangente non verticale. Quelle grandeur est mesurée par f'(a) ?","a":["Le coefficient directeur de la tangente en A.","L'ordonnée à l'origine de la tangente.","La pente de la sécante joignant A à l'origine.","La courbure de la trajectoire."],"correct":0,"why":"La dérivée est la pente de la tangente au point considéré.","active":true,"family":"V2-C1-F410"},{"id":"V2-C1-F410-V2","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Au point d'abscisse 3, la tangente à une courbe a pour équation \\(y=-2x+7\\). Quel renseignement fournit cette droite sur la fonction f ?","a":["\\(f'(3)=7\\).","\\(f'(3)=1\\).","\\(f'(3)=3\\).","\\(f'(3)=-2\\)."],"correct":3,"why":"Le coefficient de x est la pente de la tangente.","active":true,"family":"V2-C1-F410"},{"id":"V2-C1-F410-V3","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Une courbe de température présente une tangente horizontale au temps t0. Que peut-on conclure sur le taux instantané de variation, sans information supplémentaire ?","a":["La température vaut zéro en t0.","La température est nécessairement maximale en t0.","Il est nul en t0.","La température reste constante après t0."],"correct":2,"why":"Une tangente horizontale a une pente nulle ; cela ne garantit pas un extremum.","active":true,"family":"V2-C1-F410"},{"id":"V2-C1-F411-V1","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Soit u une fonction dérivable sur un intervalle I. Quelle règle donne la dérivée de \\(e^{u(x)}\\) ?","a":["\\(e^{u'(x)}\\)","\\(u(x)e^{u(x)}\\)","\\(e^{u(x)}/u'(x)\\)","\\(u'(x)e^{u(x)}\\)"],"correct":3,"why":"La règle de la chaîne multiplie la dérivée extérieure par celle de l'exposant.","active":true,"family":"V2-C1-F411"},{"id":"V2-C1-F411-V2","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=e^{3x-1}\\), un étudiant propose \\(f'(x)=e^{3x-1}\\). Quel facteur manque dans son résultat ?","a":["Le facteur -1, terme constant de l'exposant.","Le facteur x, variable de l'exposant.","Le facteur 3, dérivée de l'exposant.","Le facteur e, base de l'exponentielle."],"correct":2,"why":"La dérivée de 3x-1 vaut 3.","active":true,"family":"V2-C1-F411"},{"id":"V2-C1-F411-V3","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Une quantité est décrite par \\(G(t)=e^{-kt}\\) avec k>0. Quelle expression de G' montre que G décroît ?","a":["\\(G'(t)=ke^{-kt}\\)","\\(G'(t)=-ke^{-kt}\\)","\\(G'(t)=-te^{-kt}\\)","\\(G'(t)=e^{-k}\\)"],"correct":1,"why":"La dérivée de -kt vaut -k et l'exponentielle est positive.","active":true,"family":"V2-C1-F411"},{"id":"V2-C1-F412-V1","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Soient u et v dérivables sur I et α,β deux constantes. Quelle identité traduit la linéarité de la dérivation ?","a":["\\((\\alpha u+\\beta v)'=\\alpha u'+\\beta v'\\)","\\((\\alpha u+\\beta v)'=\\alpha\\beta u'v'\\)","\\((\\alpha u+\\beta v)'=u'+v'\\)","\\((\\alpha u+\\beta v)'=\\alpha u+\\beta v'\\)"],"correct":0,"why":"La dérivation conserve les combinaisons linéaires à coefficients constants.","active":true,"family":"V2-C1-F412"},{"id":"V2-C1-F412-V2","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Une quantité totale est la somme de deux contributions G1 et G2, toutes deux dérivables. Comment obtenir sa vitesse de variation instantanée ?","a":["Multiplier les vitesses G1' et G2'.","Additionner les valeurs G1 et G2 sans dériver.","Calculer la moyenne des deux vitesses.","Additionner les vitesses G1' et G2'."],"correct":3,"why":"La dérivée d'une somme est la somme des dérivées.","active":true,"family":"V2-C1-F412"},{"id":"V2-C1-F412-V3","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"On connaît \\(u'(2)=3\\) et \\(v'(2)=-1\\). Quelle valeur obtient-on pour la dérivée de \\(2u-v\\) au point 2 ?","a":["\\(5\\)","\\(4\\)","\\(7\\)","\\(-2\\)"],"correct":2,"why":"Par linéarité : 2×3-(-1)=7.","active":true,"family":"V2-C1-F412"},{"id":"V2-C1-F413-V1","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Soit f continue sur un intervalle I. Quelle propriété définit une primitive F de f sur I ?","a":["\\(f'(x)=F(x)\\)","\\(F'(x)=f(x)\\)","\\(F(x)=xf(x)\\) toujours.","\\(F(x)=f(x)\\) toujours."],"correct":1,"why":"Une primitive est une fonction dont la dérivée est la fonction donnée.","active":true,"family":"V2-C1-F413"},{"id":"V2-C1-F413-V2","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant veut vérifier que F est une primitive de f. Quelle relation doit-il établir pour tout x de I ?","a":["\\(F'(x)=f(x)\\)","\\(f'(x)=F(x)\\)","\\(F(x)=xf(x)\\) toujours.","\\(F(x)=f(x)\\) toujours."],"correct":0,"why":"Une primitive est une fonction dont la dérivée est la fonction donnée.","active":true,"family":"V2-C1-F413"},{"id":"V2-C1-F413-V3","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Une fonction représente un cumul F et f son taux instantané. Quelle relation traduit mathématiquement cette interprétation ?","a":["\\(f'(x)=F(x)\\)","\\(F(x)=xf(x)\\) toujours.","\\(F(x)=f(x)\\) toujours.","\\(F'(x)=f(x)\\)"],"correct":3,"why":"Une primitive est une fonction dont la dérivée est la fonction donnée.","active":true,"family":"V2-C1-F413"},{"id":"V2-C1-F414-V1","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Soit f continue sur [a,b] et F une primitive. Quelle expression calcule exactement son intégrale définie ?","a":["\\(F(a)-F(b)\\)","\\(\\int_a^b f(x)\\,dx=F(b)-F(a)\\)","\\(f(b)-f(a)\\)","\\(F(b)+F(a)\\)"],"correct":1,"why":"Le théorème fondamental exprime l'intégrale par les valeurs aux bornes d'une primitive.","active":true,"family":"V2-C1-F414"},{"id":"V2-C1-F414-V2","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant calcule une intégrale en utilisant f(b)-f(a). Quelle relation avec une primitive est correcte ?","a":["\\(\\int_a^b f(x)\\,dx=F(b)-F(a)\\)","\\(F(a)-F(b)\\)","\\(f(b)-f(a)\\)","\\(F(b)+F(a)\\)"],"correct":0,"why":"Le théorème fondamental exprime l'intégrale par les valeurs aux bornes d'une primitive.","active":true,"family":"V2-C1-F414"},{"id":"V2-C1-F414-V3","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Un cumul entre les instants a et b est calculé à partir d'une fonction primitive F. Quelle différence doit-on prendre ?","a":["\\(F(a)-F(b)\\)","\\(f(b)-f(a)\\)","\\(F(b)+F(a)\\)","\\(\\int_a^b f(x)\\,dx=F(b)-F(a)\\)"],"correct":3,"why":"Le théorème fondamental exprime l'intégrale par les valeurs aux bornes d'une primitive.","active":true,"family":"V2-C1-F414"},{"id":"V2-C1-F415-V1","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Une intensité de pluie est exprimée en mm/h et le temps en heures. Quelle unité possède son intégrale temporelle ?","a":["mm/h.","h/mm.","mm.","mm²."],"correct":2,"why":"Multiplier l'unité du taux par l'unité du temps.","active":true,"family":"V2-C1-F415"},{"id":"V2-C1-F415-V2","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"On intègre un débit de hauteur en mm par heure sur une durée mesurée en heures. Quelle unité exprime le cumul ?","a":["mm/h.","mm.","h/mm.","mm²."],"correct":1,"why":"Multiplier l'unité du taux par l'unité du temps.","active":true,"family":"V2-C1-F415"},{"id":"V2-C1-F415-V3","chapter":1,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant conserve l'unité mm/h après intégration d'un taux sur le temps. Quelle unité est correcte ?","a":["mm.","mm/h.","h/mm.","mm²."],"correct":0,"why":"Multiplier l'unité du taux par l'unité du temps.","active":true,"family":"V2-C1-F415"},{"id":"V2-C1-M401-V1","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=\\sqrt{12-3x}\\). Quel ensemble représente exactement son domaine de définition dans R ?","a":["\\(]-\\infty,4]\\)","\\(]-\\infty,4[\\)","\\([4,+\\infty[\\)","\\(]-\\infty,12]\\)"],"correct":0,"why":"Résoudre 12-3x≥0 en inversant le sens lors de la division par -3.","active":true,"family":"V2-C1-M401"},{"id":"V2-C1-M401-V2","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Une réserve évolue selon \\(V(t)=\\sqrt{90-6t}\\) pour t≥0, t étant mesuré en jours. Sur quel intervalle temporel le modèle est-il mathématiquement défini ?","a":["\\([0,15[\\)","\\([15,+\\infty[\\)","\\([0,90]\\)","\\([0,15]\\)"],"correct":3,"why":"Le temps est non négatif et 90-6t≥0.","active":true,"family":"V2-C1-M401"},{"id":"V2-C1-M401-V3","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(h(x)=\\sqrt{5-2x}\\), un étudiant propose \\([5/2,+\\infty[\\) comme domaine. Quelle erreur explique sa réponse ?","a":["Il a confondu racine carrée et logarithme.","Il a oublié que le domaine doit exclure x=0.","Il a divisé par 5 au lieu de 2.","Il a oublié d'inverser le sens de l'inégalité en divisant par -2."],"correct":3,"why":"La condition 5-2x≥0 conduit à x≤5/2.","active":true,"family":"V2-C1-M401"},{"id":"V2-C1-M402-V1","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Une population de micro-organismes dans un sol suit \\(P(t)=P_0e^{0,4t}\\). À quel instant atteint-elle trois fois sa valeur initiale ?","a":["\\(t=0,4\\ln 3\\)","\\(t=\\frac{3}{0,4}\\)","\\(t=\\frac{\\ln 3}{0,4}\\)","\\(t=\\ln(3/0,4)\\)"],"correct":2,"why":"Après division par P0, appliquer le logarithme à e^(0,4t)=3.","active":true,"family":"V2-C1-M402"},{"id":"V2-C1-M402-V2","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(e^{2x}=7\\). Quelle démarche conduit à la solution exacte dans R ?","a":["Diviser d'abord 7 par 2, puis prendre son logarithme.","Prendre le logarithme des deux membres, puis diviser par 2 : \\(x=\\ln(7)/2\\).","Prendre la racine carrée de 7 : \\(x=\\sqrt7\\).","Multiplier le logarithme de 7 par 2."],"correct":1,"why":"L'injectivité de l'exponentielle permet de résoudre 2x=ln7.","active":true,"family":"V2-C1-M402"},{"id":"V2-C1-M402-V3","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un polluant a une concentration \\(C(t)=80e^{-0,25t}\\). Quel temps est nécessaire pour atteindre 20 mg/L ?","a":["\\(4\\ln4\\) heures.","\\(4\\ln20\\) heures.","\\(\\ln4/4\\) heures.","\\(4\\ln(1/4)\\) heures."],"correct":0,"why":"La concentration est divisée par quatre : -0,25t=ln(1/4).","active":true,"family":"V2-C1-M402"},{"id":"V2-C1-M403-V1","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Soient \\(f(x)=2x+1\\) et \\(g(x)=x^2\\). Quelle valeur vaut (g composé f)(1) ?","a":["\\(3\\)","\\(5\\)","\\(9\\)","\\(4\\)"],"correct":2,"why":"Appliquer d'abord f à 1, puis élever le résultat au carré.","active":true,"family":"V2-C1-M403"},{"id":"V2-C1-M403-V2","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un traitement affine \\(f(x)=3x+1\\) est suivi d'une élévation au carré. Quelle sortie obtient-on pour l'entrée 1 ?","a":["\\(4\\)","\\(16\\)","\\(10\\)","\\(9\\)"],"correct":1,"why":"Appliquer d'abord f à 1, puis élever le résultat au carré.","active":true,"family":"V2-C1-M403"},{"id":"V2-C1-M403-V3","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant inverse l'ordre des opérations et calcule f(g(1)). Quelle valeur donne réellement g(f(1)) si f(x)=4x+1 et g(x)=x² ?","a":["\\(25\\)","\\(5\\)","\\(17\\)","\\(16\\)"],"correct":0,"why":"Appliquer d'abord f à 1, puis élever le résultat au carré.","active":true,"family":"V2-C1-M403"},{"id":"V2-C1-M404-V1","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit la bijection \\(f(x)=2x+5\\) de R dans R. Quelle fonction est sa réciproque ?","a":["\\((x+5)/2\\).","\\(2x-5\\).","\\(1/(2x+5)\\).","\\((x-5)/2\\) (en notant x l'entrée de la réciproque)."],"correct":3,"why":"Résoudre y=ax+b en isolant l'entrée initiale.","active":true,"family":"V2-C1-M404"},{"id":"V2-C1-M404-V2","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Une calibration transforme x en y=3x+7. Quelle relation permet de retrouver x à partir de y ?","a":["\\((x+7)/3\\).","\\(3x-7\\).","\\((x-7)/3\\) (en notant x l'entrée de la réciproque).","\\(1/(3x+7)\\)."],"correct":2,"why":"Résoudre y=ax+b en isolant l'entrée initiale.","active":true,"family":"V2-C1-M404"},{"id":"V2-C1-M404-V3","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant confond la réciproque de \\(f(x)=4x+9\\) avec son inverse multiplicatif. Quelle expression corrige cette confusion ?","a":["\\((x+9)/4\\).","\\((x-9)/4\\) (en notant x l'entrée de la réciproque).","\\(4x-9\\).","\\(1/(4x+9)\\)."],"correct":1,"why":"Résoudre y=ax+b en isolant l'entrée initiale.","active":true,"family":"V2-C1-M404"},{"id":"V2-C1-M405-V1","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Quelle est la valeur exacte de \\(\\lim_{x\\to0}\\frac{\\sin(3x)}{x}\\), lorsque les angles sont exprimés en radians ?","a":["\\(1\\)","\\(0\\)","\\(1/3\\)","\\(3\\)"],"correct":3,"why":"Écrire le quotient sous la forme 3 sin(3x)/(3x).","active":true,"family":"V2-C1-M405"},{"id":"V2-C1-M405-V2","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=\\frac{\\sin(5x)}{2x}\\), quelle valeur faut-il donner à f(0) pour obtenir un prolongement continu ?","a":["\\(2/5\\)","\\(1\\)","\\(5/2\\)","\\(0\\)"],"correct":2,"why":"La limite remarquable donne (5/2) sin(5x)/(5x)→5/2.","active":true,"family":"V2-C1-M405"},{"id":"V2-C1-M405-V3","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un modèle contient le quotient \\(\\sin(kh)/h\\), avec k>0 constant. Un étudiant affirme que sa limite en zéro vaut toujours 1. Quelle correction est exacte ?","a":["La limite vaut 1/k, car le sinus est divisé par h.","La limite vaut zéro, car sin(0)=0.","La limite vaut k : il faut tenir compte du facteur dans l'argument du sinus.","La limite n'existe pas, car le dénominateur s'annule en zéro."],"correct":2,"why":"Le quotient s'écrit k sin(kh)/(kh).","active":true,"family":"V2-C1-M405"},{"id":"V2-C1-M406-V1","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Calculer \\(\\lim_{x\\to2}(x^2-4)/(x-2)\\) en factorisant.","a":["\\(2\\)","\\(4\\)","0.","+∞."],"correct":1,"why":"Le quotient se simplifie en x+a pour x≠a.","active":true,"family":"V2-C1-M406"},{"id":"V2-C1-M406-V2","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un modèle présente la forme 0/0 au point 3. Quelle valeur limite de ce quotient obtient-on après simplification ?","a":["\\(6\\)","\\(3\\)","0.","+∞."],"correct":0,"why":"Le quotient se simplifie en x+a pour x≠a.","active":true,"family":"V2-C1-M406"},{"id":"V2-C1-M406-V3","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant annule numérateur et dénominateur sans factoriser. Quel résultat exact de \\((x^2-16)/(x-4)\\) au voisinage de x=4 doit-il retenir ?","a":["\\(8\\)","\\(4\\)","0.","+∞."],"correct":0,"why":"Le quotient se simplifie en x+a pour x≠a.","active":true,"family":"V2-C1-M406"},{"id":"V2-C1-M407-V1","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Une fonction f est continue sur [0,1] et vérifie f(0)=-2 et f(1)=5. Quelle conclusion garantit le TVI ?","a":["Il existe exactement une racine dans ]0,1[.","La racine est nécessairement 1/2.","Il existe au moins une racine dans ]0,1[.","Il n'existe aucune racine."],"correct":2,"why":"Zéro est strictement compris entre les valeurs aux bornes.","active":true,"family":"V2-C1-M407"},{"id":"V2-C1-M407-V2","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Une grandeur continue passe d'un écart négatif -3 à un écart positif 7. Quel événement se produit nécessairement à un instant intermédiaire ?","a":["Il existe exactement une racine dans ]0,1[.","Il existe au moins une racine dans ]0,1[.","La racine est nécessairement 1/2.","Il n'existe aucune racine."],"correct":1,"why":"Zéro est strictement compris entre les valeurs aux bornes.","active":true,"family":"V2-C1-M407"},{"id":"V2-C1-M407-V3","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant prétend que la racine de cette fonction continue est forcément unique. Quelle conclusion exacte donne seulement le TVI ?","a":["Il existe au moins une racine dans ]0,1[.","Il existe exactement une racine dans ]0,1[.","La racine est nécessairement 1/2.","Il n'existe aucune racine."],"correct":0,"why":"Zéro est strictement compris entre les valeurs aux bornes.","active":true,"family":"V2-C1-M407"},{"id":"V2-C1-M408-V1","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Quelle limite possède \\(2x\\sin(1/x)\\) en zéro ?","a":["1.","0.","+∞.","La limite n'existe pas."],"correct":1,"why":"Le module du produit est borné par a fois le module de x, qui tend vers zéro.","active":true,"family":"V2-C1-M408"},{"id":"V2-C1-M408-V2","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un modèle oscillant est multiplié par une amplitude 3x qui tend vers zéro. Quel comportement du produit près de zéro ?","a":["0.","1.","+∞.","La limite n'existe pas."],"correct":0,"why":"Le module du produit est borné par a fois le module de x, qui tend vers zéro.","active":true,"family":"V2-C1-M408"},{"id":"V2-C1-M408-V3","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant refuse de conclure car sin(1/x) n'a pas de limite. Quel résultat permet l'encadrement du produit ?","a":["1.","+∞.","La limite n'existe pas.","0."],"correct":3,"why":"Le module du produit est borné par a fois le module de x, qui tend vers zéro.","active":true,"family":"V2-C1-M408"},{"id":"V2-C1-M409-V1","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=(x^2+4)e^{-x}\\). Quelle expression de f' résulte de l'application correcte de la règle du produit ?","a":["\\((-x^2+2x-4)e^{-x}\\)","\\(2xe^{-x}\\)","\\((-x^2-2x-4)e^{-x}\\)","\\((x^2+2x+4)e^{-x}\\)"],"correct":0,"why":"Dériver les deux facteurs et additionner les deux contributions.","active":true,"family":"V2-C1-M409"},{"id":"V2-C1-M409-V2","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un modèle \\(G(t)=(t+3)e^{-2t}\\) comporte deux facteurs variables. Un étudiant ne dérive que le premier. Quel est le résultat complet ?","a":["\\(G'(t)=e^{-2t}\\)","\\(G'(t)=-2(t+3)e^{-2t}\\)","\\(G'(t)=(2t+7)e^{-2t}\\)","\\(G'(t)=(-2t-5)e^{-2t}\\)"],"correct":3,"why":"La dérivée de t+3 vaut 1 et celle de e^-2t vaut -2e^-2t.","active":true,"family":"V2-C1-M409"},{"id":"V2-C1-M409-V3","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^2\\ln x\\), x>0, quelle expression simplifiée de f' tient compte des deux facteurs ?","a":["\\(2x\\ln x\\)","\\(x\\)","\\(2x/x\\)","\\(2x\\ln x+x\\)"],"correct":3,"why":"Le terme x²/x vaut x et s'ajoute à 2x ln x.","active":true,"family":"V2-C1-M409"},{"id":"V2-C1-M410-V1","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Soient u et v dérivables, v non nulle sur I. Quelle formule donne la dérivée de leur quotient ?","a":["\\((u'v+uv')/v^2\\)","\\((u'v-uv')/v^2\\)","\\((uv'-u'v)/v^2\\)","\\(u'/v'\\)"],"correct":1,"why":"La règle du quotient impose un signe moins et le carré au dénominateur.","active":true,"family":"V2-C1-M410"},{"id":"V2-C1-M410-V2","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=(2x+1)/(x+3)\\) pour x≠-3. Quelle est sa dérivée simplifiée ?","a":["\\((4x+7)/(x+3)^2\\)","\\(5/(x+3)^2\\)","\\(2/(x+3)\\)","\\(-5/(x+3)^2\\)"],"correct":1,"why":"Le numérateur vaut 2(x+3)-(2x+1)=5.","active":true,"family":"V2-C1-M410"},{"id":"V2-C1-M410-V3","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Une mesure suit \\(G(t)=12/(1+3t)\\). Quel calcul justifie que G décroît pour t≥0 ?","a":["\\(G'(t)=-36/(1+3t)^2<0\\).","\\(G'(t)=36/(1+3t)^2>0\\).","\\(G'(t)=-12/(1+3t)<0\\).","\\(G'(t)=0\\), car le numérateur est constant."],"correct":0,"why":"Dériver l'inverse du dénominateur.","active":true,"family":"V2-C1-M410"},{"id":"V2-C1-M411-V1","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit f continue sur [a,b], dérivable sur ]a,b[, avec a<b. Quelle égalité est garantie par le théorème des accroissements finis ?","a":["Il existe c tel que \\(f'(c)=f(b)-f(a)\\).","Il existe c tel que \\(f(c)=(f'(b)-f'(a))/(b-a)\\).","Il existe c tel que \\(f'(c)=0\\), sans autre hypothèse.","Il existe c dans ]a,b[ tel que \\(f'(c)=(f(b)-f(a))/(b-a)\\)."],"correct":3,"why":"La pente instantanée coïncide au moins une fois avec la pente moyenne.","active":true,"family":"V2-C1-M411"},{"id":"V2-C1-M411-V2","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Une grandeur continue sur [2,6] et dérivable à l'intérieur passe de 14 à 30 unités. Quelle valeur de la vitesse instantanée est nécessairement atteinte à un temps intermédiaire ?","a":["16 unités par unité de temps.","8 unités par unité de temps.","4 unités par unité de temps.","22 unités par unité de temps."],"correct":2,"why":"Le taux moyen est (30-14)/(6-2)=4.","active":true,"family":"V2-C1-M411"},{"id":"V2-C1-M411-V3","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant applique le TAF à \\(f(x)=\\vert x-1\\vert\\) sur [0,2]. Quelle hypothèse empêche de conclure ?","a":["La continuité sur [0,2].","L'égalité des valeurs aux bornes, obligatoire pour le TAF.","La dérivabilité en x=1, point intérieur du segment.","La positivité de f sur le segment."],"correct":2,"why":"Le point anguleux intérieur empêche l'application du TAF.","active":true,"family":"V2-C1-M411"},{"id":"V2-C1-M412-V1","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^3-12x\\), quels extrema locaux obtient-on après étude du signe de la dérivée ?","a":["Maximum en x=2, de valeur -16 ; minimum en x=-2, de valeur 16.","Maximum en x=0, de valeur 0 ; aucun minimum.","Maximum en x=-2, de valeur 16 ; minimum en x=2, de valeur -16.","Aucun extremum, car f est un polynôme de degré impair."],"correct":2,"why":"f'=3(x²-4), positive hors de [-2,2] et négative entre les racines.","active":true,"family":"V2-C1-M412"},{"id":"V2-C1-M412-V2","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(g(x)=x^3-27x\\), un étudiant trouve les points stationnaires ±3. Quelle classification est exacte ?","a":["Minimum local en -3 ; maximum local en 3.","Maximum local en -3 ; minimum local en 3.","Deux maxima locaux.","Deux minima locaux."],"correct":1,"why":"La dérivée passe de + à - en -3 puis de - à + en 3.","active":true,"family":"V2-C1-M412"},{"id":"V2-C1-M412-V3","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(h(x)=-x^3+3x\\). Quelles sont les valeurs des extrema locaux et leurs abscisses ?","a":["Maximum 2 en -1 ; minimum -2 en 1.","Minimum -2 en -1 ; maximum 2 en 1.","Minimum 0 en 0 ; maximum 3 en 1.","Aucun extremum local."],"correct":1,"why":"h'=3(1-x²), négative hors de [-1,1] et positive entre les racines.","active":true,"family":"V2-C1-M412"},{"id":"V2-C1-M413-V1","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Calculer \\(\\int_0^2(2x+5)\\,dx\\) en évaluant une primitive aux bornes.","a":["\\(18\\).","\\(7\\).","\\(9\\).","\\(14\\) unités (dans le modèle)."],"correct":3,"why":"Évaluer ax²/2+bx entre 0 et 2.","active":true,"family":"V2-C1-M413"},{"id":"V2-C1-M413-V2","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un débit de collecte est \\(v(t)=3t+7\\) unités/h. Quel cumul entre 0 et 2 h ?","a":["\\(26\\).","\\(10\\).","\\(20\\) unités (dans le modèle).","\\(13\\)."],"correct":2,"why":"Évaluer ax²/2+bx entre 0 et 2.","active":true,"family":"V2-C1-M413"},{"id":"V2-C1-M413-V3","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant multiplie v(2) par 2 pour calculer le cumul de \\(v(t)=4t+9\\). Quelle intégrale exacte doit-il retenir ?","a":["\\(34\\).","\\(26\\) unités (dans le modèle).","\\(13\\).","\\(17\\)."],"correct":1,"why":"Évaluer ax²/2+bx entre 0 et 2.","active":true,"family":"V2-C1-M413"},{"id":"V2-C1-M414-V1","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Quel changement de variable simplifie \\(\\int 2x/(1+x^2)\\,dx\\) ?","a":["\\(u=1+x\\)","\\(u=1+x^2\\)","\\(u=2x\\)","\\(u=x^3\\)"],"correct":1,"why":"du=2x dx, le quotient devient du/u.","active":true,"family":"V2-C1-M414"},{"id":"V2-C1-M414-V2","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Dans l'intégrale d'un quotient, on reconnaît la dérivée du dénominateur 1+x². Quelle substitution est naturelle ?","a":["\\(u=1+x^2\\)","\\(u=1+x\\)","\\(u=2x\\)","\\(u=x^3\\)"],"correct":0,"why":"du=2x dx, le quotient devient du/u.","active":true,"family":"V2-C1-M414"},{"id":"V2-C1-M414-V3","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant choisit u=x dans \\(\\int 2x/(1+x^2)\\,dx\\) sans simplifier le quotient. Quelle substitution transforme l'intégrande en du/u ?","a":["\\(u=1+x\\)","\\(u=2x\\)","\\(u=x^3\\)","\\(u=1+x^2\\)"],"correct":3,"why":"du=2x dx, le quotient devient du/u.","active":true,"family":"V2-C1-M414"},{"id":"V2-C1-M415-V1","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Calculer \\(\\int_0^1(2x^2+5)\\,dx\\) en intégrant séparément chaque terme.","a":["\\((2+5)/3\\)","\\(2/2+5\\)","\\(7\\)","\\(2/3+5\\)"],"correct":3,"why":"Intégrer ax² et la constante b séparément.","active":true,"family":"V2-C1-M415"},{"id":"V2-C1-M415-V2","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un taux est donné par \\(v(t)=3t^2+7\\). Quel cumul prévoit-il sur [0,1] ?","a":["\\((3+7)/3\\)","\\(3/2+7\\)","\\(10\\)","\\(3/3+7\\)"],"correct":3,"why":"Intégrer ax² et la constante b séparément.","active":true,"family":"V2-C1-M415"},{"id":"V2-C1-M415-V3","chapter":1,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant divise la somme des deux coefficients par 3. Quel résultat exact donne l'intégrale de \\(4x^2+9\\) de 0 à 1 ?","a":["\\((4+9)/3\\)","\\(4/2+9\\)","\\(4/3+9\\)","\\(13\\)"],"correct":2,"why":"Intégrer ax² et la constante b séparément.","active":true,"family":"V2-C1-M415"},{"id":"V2-C1-D401-V1","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=\\ln(16-x^2)\\). Quelle description de son domaine et de son comportement aux bornes est exacte ?","a":["\\(D_f=]-4,4[\\) et f tend vers \\(-\\infty\\) aux deux bornes depuis l'intérieur.","\\(D_f=[-4,4]\\) et f vaut zéro aux bornes.","\\(D_f=]-4,4[\\) et f tend vers \\(+\\infty\\) aux bornes.","\\(D_f=]-\\infty,-4[\\cup]4,+\\infty[\\)."],"correct":0,"why":"Le logarithme exige un argument positif et diverge vers -∞ lorsque celui-ci tend vers zéro par valeurs positives.","active":true,"family":"V2-C1-D401"},{"id":"V2-C1-D401-V2","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(g(x)=\\ln(9-(x-2)^2)\\), quelles valeurs de x sont admissibles et quelle est l'abscisse de son maximum ?","a":["\\(x\\in[-1,5]\\) ; maximum en x=2.","\\(x\\in]-3,3[\\) ; maximum en x=0.","\\(x\\in]-1,5[\\) ; maximum en x=5.","\\(x\\in]-1,5[\\) ; maximum en x=2."],"correct":3,"why":"Le logarithme est croissant ; son argument positif atteint son maximum lorsque (x-2)²=0.","active":true,"family":"V2-C1-D401"},{"id":"V2-C1-D401-V3","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un indice de qualité est défini par \\(J(t)=\\ln(25-(t-6)^2)\\), pour t en heures. Quelle affirmation identifie correctement le domaine réel du modèle et sa valeur maximale ?","a":["\\(t\\in[1,11]\\) et \\(J(6)=25\\).","\\(t\\in]1,11[\\) et \\(J(11)=\\ln25\\).","\\(t\\in]1,11[\\) et \\(J(6)=\\ln25\\).","\\(t\\in]0,12[\\) et \\(J(6)=0\\)."],"correct":2,"why":"L'argument est positif si la distance à 6 est strictement inférieure à 5 ; son maximum est 25.","active":true,"family":"V2-C1-D401"},{"id":"V2-C1-D402-V1","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=\\sqrt{(x-2)(x+5)}\\). Quel domaine résulte d'une étude complète du signe du produit ?","a":["\\([-5,2]\\)","\\(]-\\infty,-5]\\cup[2,+\\infty[\\)","\\(]-\\infty,-5[\\cup]2,+\\infty[\\)","\\([-2,5]\\)"],"correct":1,"why":"Le produit de deux facteurs de coefficient directeur positif est non négatif hors de l'intervalle entre les racines.","active":true,"family":"V2-C1-D402"},{"id":"V2-C1-D402-V2","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un étudiant souhaite déterminer le domaine de \\(g(x)=\\sqrt{(x+1)(4-x)}\\). Quelle réponse tient compte à la fois des signes des facteurs et des points d'annulation ?","a":["\\(]-\\infty,-1]\\cup[4,+\\infty[\\)","\\([-1,4]\\)","\\(]-1,4[\\)","\\([1,4]\\)"],"correct":1,"why":"Le produit est non négatif entre -1 et 4, avec inclusion des racines.","active":true,"family":"V2-C1-D402"},{"id":"V2-C1-D402-V3","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Le modèle \\(S(t)=\\sqrt{(t-2)(8-t)}\\) représente un indice de stockage, avec t≥0. Quel intervalle rend le modèle réel, et quand l'indice atteint-il son maximum ?","a":["\\([2,8]\\) ; maximum en t=5.","\\(]2,8[\\) ; maximum en t=5.","\\([0,2]\\cup[8,+\\infty[\\) ; maximum en t=8.","\\([2,8]\\) ; maximum en t=2."],"correct":0,"why":"Le radicande vaut 9-(t-5)² : il est non négatif entre les deux racines et maximal au milieu.","active":true,"family":"V2-C1-D402"},{"id":"V2-C1-D403-V1","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"La concentration d'un polluant suit \\(C(t)=C_0e^{-2t}\\) avec C0>0. Quel temps est nécessaire pour diviser la concentration initiale par deux ?","a":["\\(t=2\\ln2\\)","\\(t=1/2\\)","\\(t=\\ln(2)\\)","\\(t=\\ln2/2\\)"],"correct":3,"why":"Prendre le logarithme de 1/2 et isoler t.","active":true,"family":"V2-C1-D403"},{"id":"V2-C1-D403-V2","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle de décroissance exponentielle de coefficient 3 atteint un seuil relatif de 50 %. Quelle durée faut-il prévoir ?","a":["\\(t=3\\ln2\\)","\\(t=1/3\\)","\\(t=\\ln2/3\\)","\\(t=\\ln(3)\\)"],"correct":2,"why":"Prendre le logarithme de 1/2 et isoler t.","active":true,"family":"V2-C1-D403"},{"id":"V2-C1-D403-V3","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un étudiant multiplie ln2 par le coefficient de décroissance 4. Quelle durée exacte donne l'équation \\(e^{-4t}=1/2\\) ?","a":["\\(t=4\\ln2\\)","\\(t=\\ln2/4\\)","\\(t=1/4\\)","\\(t=\\ln(4)\\)"],"correct":1,"why":"Prendre le logarithme de 1/2 et isoler t.","active":true,"family":"V2-C1-D403"},{"id":"V2-C1-D404-V1","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour un modèle de réponse instrumentale \\(R(x)=\\sqrt{1+6x}\\), quelle est la limite de \\((R(x)-R(0))/x\\) en zéro ?","a":["\\(6\\)","\\(1/3\\)","\\(0\\)","\\(3\\)"],"correct":3,"why":"Rationaliser : le quotient vaut 6/(sqrt(1+6x)+1), de limite 3.","active":true,"family":"V2-C1-D404"},{"id":"V2-C1-D404-V2","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=\\frac{\\sqrt{4+3x}-2}{x}\\) pour x≠0 près de zéro. Quelle valeur et quelle méthode permettent de la prolonger continûment ?","a":["\\(3/2\\), en remplaçant le dénominateur par 2.","\\(3\\), en annulant directement les racines.","\\(3/4\\), en multipliant par le conjugué du numérateur.","\\(0\\), car le numérateur tend vers zéro."],"correct":2,"why":"Le quotient est 3/(sqrt(4+3x)+2), dont le dénominateur tend vers 4.","active":true,"family":"V2-C1-D404"},{"id":"V2-C1-D404-V3","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un étudiant rationalise \\(\\frac{\\sqrt{9+2h}-3}{h}\\) et obtient \\(2/(\\sqrt{9+2h}-3)\\). Quelle est la correction et la limite exacte ?","a":["Il faut un signe + au dénominateur ; la limite vaut 2/3.","Il faut un signe + au dénominateur ; la limite vaut \\(1/3\\).","L'expression obtenue est correcte et la limite vaut +∞.","Le numérateur doit devenir h ; la limite vaut zéro."],"correct":1,"why":"Le produit par le conjugué donne 2/(sqrt(9+2h)+3), de limite 2/6.","active":true,"family":"V2-C1-D404"},{"id":"V2-C1-D405-V1","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(x>0\\), déterminer la limite lorsque x tend vers +∞ de \\(\\sqrt{x^2+10x+4}-x\\).","a":["\\(5\\)","\\(10\\)","\\(0\\)","\\(+\\infty\\)"],"correct":0,"why":"Rationaliser puis diviser numérateur et dénominateur par x.","active":true,"family":"V2-C1-D405"},{"id":"V2-C1-D405-V2","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Deux expressions non bornées sont soustraites dans \\(g(t)=\\sqrt{4t^2+12t}-2t\\). Quelle limite obtient-on pour t tendant vers +∞ ?","a":["\\(3\\)","\\(6\\)","\\(0\\)","\\(+\\infty\\)"],"correct":0,"why":"Le conjugué donne 12t/(sqrt(4t²+12t)+2t), de limite 12/4=3.","active":true,"family":"V2-C1-D405"},{"id":"V2-C1-D405-V3","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Une modélisation donne \\(R(s)=\\sqrt{s^2+8s}-s\\) pour s>0. Quel est le comportement à long terme de R, malgré la divergence de chacun des deux termes ?","a":["R tend vers zéro, car les deux termes sont équivalents.","R tend vers +∞, car le premier terme diverge.","R tend vers 8, car 8 est le coefficient de s.","R tend vers 4, car la rationalisation élimine la forme indéterminée ∞-∞."],"correct":3,"why":"R=8/(sqrt(1+8/s)+1), donc R→4.","active":true,"family":"V2-C1-D405"},{"id":"V2-C1-D406-V1","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Calculer \\(\\lim_{x\\to0}(1-\\cos(2x))/x^2\\) en utilisant une identité trigonométrique.","a":["\\(4\\)","0.","\\(4/2\\)","\\(-4/2\\)"],"correct":2,"why":"Utiliser 1-cos u=2sin²(u/2) et sin v/v→1.","active":true,"family":"V2-C1-D406"},{"id":"V2-C1-D406-V2","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle contient une variation de cosinus rapportée à x². Quelle limite de \\((1-\\cos(3x))/x^2\\) mesure l'ordre quadratique ?","a":["\\(9\\)","\\(9/2\\)","0.","\\(-9/2\\)"],"correct":1,"why":"Utiliser 1-cos u=2sin²(u/2) et sin v/v→1.","active":true,"family":"V2-C1-D406"},{"id":"V2-C1-D406-V3","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un étudiant applique la limite de sin u/u sans tenir compte du carré de l'argument. Quelle valeur exacte faut-il retenir ?","a":["\\(16\\)","\\(16/2\\)","0.","\\(-16/2\\)"],"correct":1,"why":"Utiliser 1-cos u=2sin²(u/2) et sin v/v→1.","active":true,"family":"V2-C1-D406"},{"id":"V2-C1-D407-V1","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Une fonction continue strictement croissante prend des valeurs négative et positive aux bornes d'un segment. Combien de racines intérieures sont garanties ?","a":["Au moins deux.","Aucune.","Exactement une.","Une infinité."],"correct":2,"why":"L'existence découle du TVI et l'unicité de la stricte croissance.","active":true,"family":"V2-C1-D407"},{"id":"V2-C1-D407-V2","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Une concentration ajustée par rapport à un seuil est continue, strictement croissante, et passe de -3 à 7. Combien de fois franchit-elle zéro ?","a":["Au moins deux.","Aucune.","Exactement une.","Une infinité."],"correct":2,"why":"L'existence découle du TVI et l'unicité de la stricte croissance.","active":true,"family":"V2-C1-D407"},{"id":"V2-C1-D407-V3","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un étudiant invoque uniquement le TVI pour justifier l'unicité d'une racine. Avec continuité, signes opposés et stricte croissance, quelle conclusion complète est exacte ?","a":["Au moins deux.","Exactement une.","Aucune.","Une infinité."],"correct":1,"why":"L'existence découle du TVI et l'unicité de la stricte croissance.","active":true,"family":"V2-C1-D407"},{"id":"V2-C1-D408-V1","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^3-12x\\) sur [-4,4], quels points réalisent les extrema globaux ?","a":["Maximum 16 en -2 et 4 ; minimum -16 en -4 et 2.","Maximum 16 seulement en -2 ; minimum -16 seulement en 2.","Maximum 64 en 4 ; minimum -64 en -4.","Maximum 16 en 2 et 4 ; minimum -16 en -4 et -2."],"correct":0,"why":"Comparer les valeurs aux deux points stationnaires et aux deux bornes.","active":true,"family":"V2-C1-D408"},{"id":"V2-C1-D408-V2","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(g(x)=x^3-3x\\) sur [0,3], où sont atteints les extrema globaux ?","a":["Minimum 0 en 0 ; maximum 2 en 1.","Minimum -2 en 1 ; maximum 0 en 0.","Minimum -2 en 1 ; aucun maximum.","Minimum -2 en 1 ; maximum 18 en 3."],"correct":3,"why":"Comparer g(0)=0, g(1)=-2 et g(3)=18.","active":true,"family":"V2-C1-D408"},{"id":"V2-C1-D408-V3","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(h(x)=-x^3+12x\\) sur [0,5], quels sont le maximum et le minimum globaux ?","a":["Maximum 16 en 2 ; minimum 0 en 0.","Maximum 60 en 5 ; minimum -16 en 2.","Maximum 16 en 2 ; minimum -65 en 5.","Maximum 0 en 0 ; minimum -65 en 5."],"correct":2,"why":"h'=12-3x² s'annule en 2 ; comparer h(0), h(2) et h(5).","active":true,"family":"V2-C1-D408"},{"id":"V2-C1-D409-V1","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Le débit d'une rivière \\(G(t)=8+3te^{-2t}\\) est étudié pour t≥0. Quel couple donne l'instant du maximum et sa valeur exacte ?","a":["\\(t=2,\\ G_{\\max}=8+6e^{-4}\\)","\\(t=1/2,\\ G_{\\max}=8+3/(2e)\\)","\\(t=1/2,\\ G_{\\max}=8+3e/2\\)","\\(t=0,\\ G_{\\max}=8\\)"],"correct":1,"why":"G'=3(1-2t)e^-2t change de signe de + à - en 1/2.","active":true,"family":"V2-C1-D409"},{"id":"V2-C1-D409-V2","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"L'indice de ruissellement est \\(G(t)=4t^2e^{-t}\\) pour t≥0. Quel est son maximum global et pourquoi t=0 n'est-il pas maximiseur ?","a":["Maximum \\(4e^{-1}\\) en t=1 ; G décroît à partir de 1.","Maximum \\(16e^{-2}\\) en t=2 ; G croît entre 0 et 2.","Maximum 0 en t=0, car G'(0)=0.","Maximum \\(16e^2\\) en t=2."],"correct":1,"why":"G'=4t(2-t)e^-t.","active":true,"family":"V2-C1-D409"},{"id":"V2-C1-D409-V3","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(G(t)=12+6te^{-3t}\\) sur t≥0, quelle est l'amplitude maximale de l'excès G(t)-12 ?","a":["\\(2/e\\), atteinte en t=1/3.","\\(6/e\\), atteinte en t=1.","\\(2e\\), atteinte en t=1/3.","\\(6\\), atteinte en t=0."],"correct":0,"why":"Dériver 6te^-3t puis évaluer au point t=1/3.","active":true,"family":"V2-C1-D409"},{"id":"V2-C1-D410-V1","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"La biomasse d'une parcelle suit \\(G(t)=40-30e^{-0,2t}\\) pour t≥0. Que révèlent les signes de G' et G'' ?","a":["G diminue et sa vitesse de diminution augmente.","G augmente et sa vitesse de croissance diminue.","G augmente et sa vitesse de croissance augmente.","G diminue mais sa vitesse est constante."],"correct":1,"why":"G'=6e^-0,2t>0 et G''=-1,2e^-0,2t<0.","active":true,"family":"V2-C1-D410"},{"id":"V2-C1-D410-V2","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour un stock de polluant \\(G(t)=15+20e^{-0,5t}\\), quelle interprétation des dérivées est rigoureuse ?","a":["G décroît, mais le taux de diminution en valeur absolue s'atténue.","G décroît et sa diminution s'accélère.","G croît à vitesse décroissante.","G est constante car sa dérivée tend vers zéro."],"correct":0,"why":"G'=-10e^-0,5t<0, G''=5e^-0,5t>0.","active":true,"family":"V2-C1-D410"},{"id":"V2-C1-D410-V3","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle de stockage d'eau \\(G(t)=60(1-e^{-t/3})\\) représente une accumulation. Quelle description combine variations et convexité ?","a":["Croissante et convexe ; sa vitesse augmente.","Décroissante et convexe ; sa vitesse est négative.","Croissante et affine ; sa vitesse est constante.","Croissante et concave ; sa vitesse tend vers zéro."],"correct":3,"why":"G'=20e^-t/3>0 et G''=-(20/3)e^-t/3<0.","active":true,"family":"V2-C1-D410"},{"id":"V2-C1-D411-V1","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=\\vert x-1\\vert\\) sur [0,2], quelle hypothèse empêche d'invoquer Rolle malgré l'égalité des images aux bornes ?","a":["f n'est pas dérivable en x=1, qui est intérieur.","f n'est pas continue au point 1.","f(0) et f(2) sont distinctes.","f est strictement positive sur le segment."],"correct":0,"why":"Les dérivées latérales valent -1 et 1.","active":true,"family":"V2-C1-D411"},{"id":"V2-C1-D411-V2","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"On considère \\(f(x)=\\sqrt{x}\\) sur [0,4]. Un étudiant refuse d'appliquer le TAF parce que f' n'existe pas en 0. Quelle réponse est exacte ?","a":["Le TAF s'applique : la dérivabilité n'est exigée que sur ]0,4[.","Le TAF est impossible dès qu'une dérivée n'existe pas à une borne.","Le TAF exige f(0)=f(4), ce qui est faux.","Le TAF exige une dérivée seconde continue."],"correct":0,"why":"f est continue sur [0,4] et dérivable sur ]0,4[.","active":true,"family":"V2-C1-D411"},{"id":"V2-C1-D411-V3","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=\\sqrt{1-x^2}\\) sur [-1,1], quelle conclusion est correcte ?","a":["Rolle ne s'applique pas car f' n'existe pas aux bornes.","Rolle s'applique et impose f'(x)=0 pour tout x.","Rolle exige que f soit strictement monotone.","Rolle s'applique et f'(0)=0, malgré les tangentes verticales aux bornes."],"correct":3,"why":"Les valeurs aux bornes sont nulles et la fonction est dérivable à l'intérieur.","active":true,"family":"V2-C1-D411"},{"id":"V2-C1-D412-V1","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Une fonction dérivable satisfait \\(\\vert f'(x)\\vert\\le0,4\\) sur [2,7]. Quel écart maximal entre f(2) et f(7) peut-on garantir ?","a":["2 unités.","0,4 unité.","12,5 unités.","7 unités."],"correct":0,"why":"L'inégalité des accroissements finis majore l'écart par 0,4×5.","active":true,"family":"V2-C1-D412"},{"id":"V2-C1-D412-V2","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle a un taux borné en module par 2,5 unités/h sur [1,4]. Sachant G(1)=10, quel encadrement le plus précis de G(4) est garanti ?","a":["\\([7,5;12,5]\\)","\\([10;17,5]\\)","\\([-7,5;7,5]\\)","\\([2,5;17,5]\\)"],"correct":3,"why":"Le TAF impose un écart maximal de 2,5×3=7,5.","active":true,"family":"V2-C1-D412"},{"id":"V2-C1-D412-V3","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour une fonction dérivable dont la dérivée est comprise entre -3 et -1 sur [0,4], quelle affirmation quantitative et qualitative est certaine ?","a":["Elle croît et f(4)-f(0) appartient à [4,12].","Elle décroît et f(4)-f(0) appartient à [-3,-1].","Elle est constante si f(0)=0.","Elle décroît et f(4)-f(0) appartient à [-12,-4]."],"correct":3,"why":"Multiplier les bornes négatives de la dérivée par la longueur 4.","active":true,"family":"V2-C1-D412"},{"id":"V2-C1-D413-V1","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Calculer \\(\\int_0^1xe^{ 2x^2}\\,dx\\) en choisissant une substitution adaptée.","a":["\\((e^{ 2 }-1)/2\\)","\\((e^{ 2 }-1)/(2\\cdot 2)\\)","\\(e^{ 2 }-1\\)","\\(e^{ 2 }/(2\\cdot 2)\\)"],"correct":1,"why":"Poser u=ax², du=2ax dx.","active":true,"family":"V2-C1-D413"},{"id":"V2-C1-D413-V2","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un taux est \\(v(t)=te^{ 3t^2}\\). Quel cumul exact sur [0,1] tient compte de la dérivée de l'exposant ?","a":["\\((e^{ 3 }-1)/(2\\cdot 3)\\)","\\((e^{ 3 }-1)/3\\)","\\(e^{ 3 }-1\\)","\\(e^{ 3 }/(2\\cdot 3)\\)"],"correct":0,"why":"Poser u=ax², du=2ax dx.","active":true,"family":"V2-C1-D413"},{"id":"V2-C1-D413-V3","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un étudiant oublie le facteur 24 dans l'intégration de xe^(ax²). Quelle valeur exacte obtient-on sur [0,1] ?","a":["\\((e^{ 4 }-1)/(2\\cdot 4)\\)","\\((e^{ 4 }-1)/4\\)","\\(e^{ 4 }-1\\)","\\(e^{ 4 }/(2\\cdot 4)\\)"],"correct":0,"why":"Poser u=ax², du=2ax dx.","active":true,"family":"V2-C1-D413"},{"id":"V2-C1-D414-V1","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un débit résiduel suit \\(Q(t)=5e^{-2t}\\) unités/h pour t≥0. Quel volume cumulé théorique obtient-on sur [0,+∞[ ?","a":["\\(5/2\\)","\\(2/5\\)","\\(5\\)","+∞."],"correct":0,"why":"Intégrer jusqu'à T puis faire tendre T vers +∞ ; e^-aT tend vers zéro.","active":true,"family":"V2-C1-D414"},{"id":"V2-C1-D414-V2","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle de disparition exponentielle fournit le taux \\(7e^{-3t}\\). Quelle quantité totale finie est prédite par l'intégrale impropre ?","a":["\\(3/7\\)","\\(7\\)","+∞.","\\(7/3\\)"],"correct":3,"why":"Intégrer jusqu'à T puis faire tendre T vers +∞ ; e^-aT tend vers zéro.","active":true,"family":"V2-C1-D414"},{"id":"V2-C1-D414-V3","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un étudiant pense qu'une durée infinie implique un cumul infini pour ce taux. Quelle valeur exacte corrige cette erreur ?","a":["\\(4/9\\)","\\(9\\)","+∞.","\\(9/4\\)"],"correct":3,"why":"Intégrer jusqu'à T puis faire tendre T vers +∞ ; e^-aT tend vers zéro.","active":true,"family":"V2-C1-D414"},{"id":"V2-C1-D415-V1","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=2x^2\\) sur [0,2], quelle approximation par deux trapèzes de largeur 1 obtient-on ?","a":["\\(8\\)","\\(16/3\\)","\\(10\\)","\\(6\\)"],"correct":3,"why":"La somme est (0+a)/2+(a+4a)/2=3a.","active":true,"family":"V2-C1-D415"},{"id":"V2-C1-D415-V2","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un débit Q(t)=3t² est mesuré aux instants 0,1,2. Quel volume approché donne la somme des deux trapèzes ?","a":["\\(12\\)","\\(24/3\\)","\\(9\\)","\\(15\\)"],"correct":2,"why":"La somme est (0+a)/2+(a+4a)/2=3a.","active":true,"family":"V2-C1-D415"},{"id":"V2-C1-D415-V3","chapter":1,"level":"difficile","usage":"ENTRAINEMENT","q":"Un étudiant compte chaque valeur de bord deux fois dans la formule composite. Quelle approximation correcte donne deux trapèzes sur [0,2] pour f(x)=4x² ?","a":["\\(16\\)","\\(32/3\\)","\\(12\\)","\\(20\\)"],"correct":2,"why":"La somme est (0+a)/2+(a+4a)/2=3a.","active":true,"family":"V2-C1-D415"}]);
